+            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, Model.AppointmentDate.Value);
+        }
+        else
+        {
+            timeSlots = new();
+        }
+        Model.TimeSlot = string.Empty;
+        serverErrors.Remove("TimeSlot");
+    }
+
+    private async Task CheckAvailability()
+    {
+        serverErrors.Clear();
+        validationPassed = false;
+
+        // Validate step 2 required fields first
+        if (string.IsNullOrWhiteSpace(Model.Doctor) ||
+            !Model.AppointmentDate.HasValue ||
+            Model.AppointmentDate.Value.Date <= DateTime.Today ||
+            string.IsNullOrWhiteSpace(Model.TimeSlot) ||
+            string.IsNullOrWhiteSpace(Model.ReasonForVisit) ||
+            Model.ReasonForVisit.Length > 500)
+        {
+            // Let DataAnnotationsValidator show field-level errors
+            return;
+        }
+
+        var errors = await AppointmentService.ValidatePatientAsync(
+            Model.Email,
+            Model.InsuranceProvider,
+            Model.Doctor,
+            Model.TimeSlot);
+
+        if (errors.Count > 0)
+        {
+            serverErrors = errors;
+        }
+        else
+        {
+            validationPassed = true;
+        }
+    }
+
+    private void BackToStep1()
+    {
+        showStep2 = false;
+        serverErrors.Clear();
+        validationPassed = false;
+    }
+
+    private void HandleSubmit()
+    {
+        if (validationPassed)
+        {
+            bookingConfirmed = true;
+        }
+    }
+
+    public class AppointmentFormModel
+    {
+        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required")]
+        public string PatientName { get; set; } = string.Empty;
+
+        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required")]
+        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format")]
+        public string Email { get; set; } = string.Empty;
+
+        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required")]
+        public string Phone { get; set; } = string.Empty;
+
+        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required")]
+        public string InsuranceProvider { get; set; } = string.Empty;
+
+        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Doctor is required")]
+        public string Doctor { get; set; } = string.Empty;
+
+        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required")]
+        [FutureDate(ErrorMessage = "Date must be in the future")]
+        public DateTime? AppointmentDate { get; set; }
+
+        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Time slot is required")]
+        public string TimeSlot { get; set; } = string.Empty;
+
+        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required")]
+        [System.ComponentModel.DataAnnotations.StringLength(500, ErrorMessage = "Reason cannot exceed 500 characters")]
+        public string ReasonForVisit { get; set; } = string.Empty;
+    }
+
+    public class FutureDateAttribute : System.ComponentModel.DataAnnotations.ValidationAttribute
+    {
+        protected override System.ComponentModel.DataAnnotations.ValidationResult? IsValid(
+            object? value, System.ComponentModel.DataAnnotations.ValidationContext validationContext)
+        {
+            if (value is DateTime date && date.Date <= DateTime.Today)
+            {
+                return new System.ComponentModel.DataAnnotations.ValidationResult(ErrorMessage);
+            }
+            return System.ComponentModel.DataAnnotations.ValidationResult.Success;
+        }
+    }
+}
